module alu8(a, b, op, result, zero, carry);
  input  [7:0] a;
  input  [7:0] b;
  input  [2:0] op;
  output [7:0] result;
  output zero;
  output carry;

  reg [7:0] result;
  reg       carry;

  wire [8:0] add_ext;
  wire [8:0] sub_ext;

  assign add_ext = {1'b0, a} + {1'b0, b};
  assign sub_ext = {1'b0, a} - {1'b0, b};

  always @* begin
    result = 8'b00000000;
    carry  = 1'b0;

    case (op)
      3'b000: begin
        result = add_ext[7:0];
        carry  = add_ext[8];
      end

      3'b001: begin
        result = sub_ext[7:0];
        carry  = (a < b);
      end

      3'b010: begin
        result = a & b;
        carry  = 1'b0;
      end

      3'b011: begin
        result = a | b;
        carry  = 1'b0;
      end

      3'b100: begin
        result = a ^ b;
        carry  = 1'b0;
      end

      3'b101: begin
        result = ~a;
        carry  = 1'b0;
      end

      3'b110: begin
        result = {a[6:0], 1'b0};
        carry  = 1'b0;
      end

      3'b111: begin
        result = {1'b0, a[7:1]};
        carry  = 1'b0;
      end
    endcase
  end

  assign zero = (result == 8'b00000000);

endmodule

